using namespace cg3::cgal::internal;

// Create a Delaunay triangulation
DT dt;
for (const Point2d& p : points) {
    dt.insert(Point_2(p.x(), p.y()));
}

// Create a Voronoi diagram from the Delaunay triangulation
VD vd(dt);

std::vector<std::vector<Point2d>> result;
result.reserve(points.size());

// Iterate through each site (input point) to get its Voronoi cell
for (const Point2d& p : points) {
    // Locate the feature in the Voronoi diagram corresponding to this site
    Locate_result lr = vd.locate(Point_2(p.x(), p.y()));

    // Check if the location result is a vertex
    if (Vertex_handle* v = boost::get<Vertex_handle>(&lr)) {
        // If it's a vertex, get its incident halfedges
        Ccb_halfedge_circulator ec_start = (*v)->incident_halfedges();
        Ccb_halfedge_circulator ec = ec_start;

        std::vector<Point2d> cell_vertices;

        // Collect all vertices of the Voronoi cell by traversing the CCB
        do {
            Point_2 source = ec->source()->point();
            cell_vertices.emplace_back(source.x(), source.y());
            ++ec;
        } while (ec != ec_start);

        result.push_back(cell_vertices);
    } else {
        // For non-vertex features, return an empty cell
        result.emplace_back();
    }
}

return result;

